"""Source-grounded editorial About page. Counts come from the current build inputs."""
from pathlib import Path
from html import escape as e
import json, shutil
ROOT=Path(__file__).resolve().parent

def build_about(page, urls, articles, glossary, out, base):
    from calculators import TOOLS
    stocks=json.loads((ROOT/'stocks.json').read_text())
    for name in ['about.css']:shutil.copyfile(ROOT/name,Path(out)/name)
    stats=[(len(stocks),'Aktien im Verzeichnis','Notierungen, keine Zusage vollständiger Marktabdeckung.'),(len(glossary),'Glossarbegriffe','Mit Quellen, Einordnung und weiterführenden Fragen.'),(len(TOOLS),'Finanzrechner','Mit offen erklärten Formeln und Modellgrenzen.'),(len(articles),'Redaktionelle Beiträge','Im aktuellen Inhaltsbestand dieses Builds.')]
    cards=''.join('<div class="about-stat"><strong>'+str(n)+'</strong><h3>'+e(label)+'</h3><p>'+e(note)+'</p></div>' for n,label,note in stats)
    tools=[('/aktien/','01','Aktien entdecken','Suche nach Name, Ticker oder vorhandener ISIN. Eigene Seiten zeigen die Notierung, Datenstand und verfügbare Kursinformationen. Nicht jede Aktie oder jeder Handelsplatz ist abgedeckt.'),('/rechner/','02','Annahmen durchrechnen','Sparplan, Zinseszins, ETF-Kosten, Entnahmeplan, Inflation, Kredit, Rendite und Dividenden. Du bestimmst die Eingaben. Ein Modell ist keine Prognose.'),('/vergleiche/','03','Bedingungen vergleichen','Ausgewählte Tagesgeld- und Depotbedingungen, eigene Kostenmodelle und ein amtlicher Zinsmonitor. Keine vollständige Marktübersicht, keine bezahlte Bestenliste.'),('/glossar/','04','Begriffe verstehen','Von Aktie bis Zins: verständliche Erklärungen, Quellen und Hinweise darauf, wo eine einfache Faustregel nicht mehr reicht.'),('/heatmap/','05','Bewegungen einordnen','Die Heatmap macht unterschiedliche Tagesveränderungen sichtbar. Quelle und Zeitpunkt zählen: Farben sind keine Kauf- oder Verkaufssignale.'),('/berichte/','06','Den Überblick mitnehmen','Der PDF-Marktbericht bündelt verfügbare Marktdaten und Inhalte. Ein kompaktes Dokument zum Lesen und Nachschlagen, kein persönlicher Anlageplan.')]
    toolcards=''.join('<a class="about-tool" href="'+href+'"><span class="about-num">'+n+'</span><h3>'+title+'</h3><p>'+text+'</p><span class="about-arrow" aria-hidden="true">↗</span></a>' for href,n,title,text in tools)
    body='''<link rel="stylesheet" href="/about.css"><main class="about-wrap">
<section class="about-hero" aria-labelledby="about-title"><div><p class="about-eyebrow">ÜBER FINANZ ADJUST</p><h1 id="about-title">Mehr verstehen.<br>Selbst entscheiden.</h1><p class="about-lead">Finanznachrichten, Marktdaten und Werkzeuge gehören zusammen. Wir bringen sie an einen Ort und zeigen, worauf die Angaben beruhen.</p><p>finanz adjust ist ein deutschsprachiges Finanzangebot von Philipp Paulik. Die Inhalte erscheinen unter der Bezeichnung FA Redaktion. Unser Ziel: Orientierung geben, ohne dir die Entscheidung über dein Geld abzunehmen.</p><div class="about-actions"><a class="btn" href="#angebot">Das Angebot entdecken</a><a class="about-link" href="#redaktion">So arbeiten wir ↓</a></div></div><div class="about-visual" aria-label="Unser Prinzip: Daten, Kontext und eigene Entscheidung"><div class="about-orbit"></div><div class="about-v-label v-one">DATEN<span>Quelle &amp; Zeitpunkt</span></div><div class="about-v-label v-two">KONTEXT<span>Chancen &amp; Grenzen</span></div><div class="about-v-label v-three">DU<span>Deine Entscheidung</span></div><svg viewBox="0 0 320 260" aria-hidden="true"><path d="M22 205L80 167L130 184L188 106L235 131L298 54"/><circle cx="188" cy="106" r="6"/></svg><p>Kein Signal. Ein besserer Überblick.</p></div></section>
<section class="about-stats" aria-label="Umfang des aktuellen Angebots">'''+cards+'''</section><p class="about-caption">Die Zahlen werden aus dem Inhaltsbestand beim Seitenaufbau gezählt. Sie messen Umfang, nicht Reichweite, Qualität oder eine lückenlose Datenabdeckung.</p>
<section class="about-section about-mission"><div><p class="about-eyebrow">UNSER ANSPRUCH</p><h2>Einordnen statt antreiben.</h2></div><div><p>Zwischen Schlagzeilen, Kurslisten und Produktangeboten fehlt oft das Entscheidende: Was bedeutet eine Zahl eigentlich? Von wann ist sie? Welche Annahme steckt in einer Rechnung? Und was lässt sie offen?</p><p>Genau dort setzt finanz adjust an. Nachrichten liefern den Anlass. Quellen und Daten geben den überprüfbaren Bezug. Erklärungen und Rechner helfen, Zusammenhänge selbst nachzuvollziehen. Keine Dringlichkeit um der Dringlichkeit willen, keine Kursziele und keine pauschalen Handlungsaufforderungen.</p><p>Wir ersetzen weder eigene Recherche noch eine persönliche Beratung. Fehler und Datenlücken bleiben möglich. Deshalb machen wir ihre Grenzen sichtbar, statt Vollständigkeit oder sichere Ergebnisse zu versprechen.</p></div></section>
<section class="about-section" id="angebot"><p class="about-eyebrow">WAS DU NUTZEN KANNST</p><h2>Vom ersten Begriff bis zur eigenen Rechnung.</h2><p class="about-intro">Kostenlos zugängliche Inhalte und Werkzeuge. Die passende Frage entscheidet, wo du anfängst.</p><div class="about-tools">'''+toolcards+'''</div></section>
<section class="about-section" id="redaktion"><p class="about-eyebrow">REDAKTION &amp; KI</p><h2>Der Weg vom Thema zum Beitrag.</h2><p class="about-intro">KI-Unterstützung ist Teil des Angebots und wird offengelegt. Automatisierung ist dabei kein Beleg für Richtigkeit und ersetzt keine Quellenprüfung.</p><ol class="about-process"><li><h3>Thema und Quellen</h3><p>Ausgangspunkt sind finanzbezogene Fragen und zugängliche Belege. Redaktionelle Beiträge nennen ihre verwendeten Quellen. Aggregierte externe Schlagzeilen sind von eigenen Artikeln zu unterscheiden und führen zur Originalquelle.</p></li><li><h3>Entwurf und Einordnung</h3><p>KI-Werkzeuge können Recherche, Textentwürfe und Gestaltung unterstützen. Texte und Bilder können mit KI entstanden sein. Für Zahlen, Zitate oder Aussagen genügt ein plausibel klingender Entwurf nicht: Maßgeblich bleibt der Beleg.</p></li><li><h3>Prüfpunkte und Datenstand</h3><p>Für eine belastbare Einordnung zählen Originalquelle, Veröffentlichungsdatum, Einheit, Zeitraum und Einschränkungen. Kurse verschiedener Börsenplätze oder Währungen dürfen nicht still gleichgesetzt werden. Berechnungen müssen ihre Annahmen und Grenzen nennen.</p></li><li><h3>Veröffentlichung und Korrektur</h3><p>Die redaktionelle Verantwortung liegt bei Philipp Paulik. Hinweise auf Fehler gehören zum Betrieb eines Informationsangebots. Inhaltliche Korrekturen sollen nachvollziehbar sein; unseren Umgang damit beschreibt die <a href="/korrekturen/">Korrekturseite</a>.</p></li></ol><div class="about-note"><h3>Was wir nicht behaupten</h3><p>Ein KI-Hinweis ist kein Gütesiegel. Quellenangaben garantieren keine Fehlerfreiheit. FA Redaktion ist die Bezeichnung dieses Angebots, keine Behauptung eines großen Teams oder einer externen Zertifizierung. Eine besondere Prüfung oder Freigabe sollte nur angenommen werden, wenn sie am konkreten Inhalt belegt ist.</p><a class="about-link" href="/transparenz/">Mehr zur KI-Transparenz →</a></div></section>
<section class="about-section" id="daten"><p class="about-eyebrow">DATEN &amp; NACHVOLLZIEHBARKEIT</p><h2>Die Quelle gehört zur Information.</h2><div class="about-data"><article><h3>Marktdaten</h3><p>Kursdaten kommen je nach Bereich und Verfügbarkeit von Twelve Data beziehungsweise ergänzenden Quellen. Aktienseiten zeigen Handelsplatz, Währung und den verfügbaren Kurszeitpunkt. Die Aktualisierung beim Seitenaufbau ist kein Live-Ticker im Browser.</p><p>Wenn kein nutzbarer API-Kurs vorliegt, kann auf dafür eingerichteten Aktienseiten ein offizielles TradingView-Widget nach ausdrücklichem Klick geladen werden. Erst dann werden Daten an TradingView übertragen. Details stehen im <a href="/datenschutz/">Datenschutz</a>.</p></article><article><h3>Unternehmensdaten und Erklärungen</h3><p>Ein Teil der Unternehmensseiten enthält Registerangaben aus SEC EDGAR. Stammdaten und ISINs haben eigene Quellen. Das Glossar verweist auf Belege und trennt die kurze Erklärung von wichtigen Einschränkungen.</p><p>Ein fehlender Wert ist kein Nullwert. Ein alter Kurs ist kein neuer Trade. Historische Daten sind keine Zusage für die Zukunft.</p></article><article><h3>Zinsen, Vergleiche und Modelle</h3><p>Der Zinsmonitor nutzt amtliche EZB-Statistiken mit dem jeweiligen Monatsstand. Die Vergleiche zeigen eine kuratierte Auswahl von Bedingungen und verlinken die Datenquelle beziehungsweise den Anbieter.</p><p>Die Rechner erklären Formeln und Modellannahmen. Steuern, Kosten, Schwankungen oder individuelle Vertragsdetails sind nur enthalten, wenn das jeweilige Werkzeug sie ausdrücklich berücksichtigt.</p></article><article><h3>Schlagzeilen und eigene Inhalte</h3><p>Die Nachrichtenseite bündelt externe Meldungen mit Quellenlink. Das ist von Einordnungen der FA Redaktion zu unterscheiden. Ein Quellenlink ist keine Zustimmung zu allen Aussagen der verlinkten Seite.</p><p>Die <a href="/quellen/">Quellenübersicht</a> erklärt die verwendeten Datenwege. Für die Aktualität einer konkreten Zahl zählt immer die Angabe direkt am Datensatz oder Beitrag.</p></article></div></section>
<section class="about-section about-values"><div><p class="about-eyebrow">WAS DIR WICHTIG SEIN DARF</p><h2>Klare Grenzen.<br>Klare Verantwortung.</h2></div><div><h3>Keine persönliche Anlageberatung</h3><p>Information und Modellrechnung sind keine Empfehlung zum Kauf, Verkauf oder Abschluss. Wertpapiere und andere Finanzprodukte können erhebliche Verluste verursachen. Lies unseren <a href="/risikohinweis/">Risikohinweis</a>.</p><h3>Werbung erkennbar halten</h3><p>Werbliche Inhalte und Affiliate-Verbindungen müssen als solche gekennzeichnet sein. Ein Produktlink ist keine automatische Empfehlung. Die Vergleichsseiten nennen ihren Auswahlumfang und ihren aktuellen Affiliate-Status direkt am Angebot. Informationen für mögliche Werbepartner stehen auf der <a href="/werben/">Werbeseite</a>.</p><h3>Keine erfundene Autorität</h3><p>Wir werben hier nicht mit erfundenen Auszeichnungen, Teamfotos, Kundenzahlen oder Zitaten. Umfangszahlen stammen aus dem Bestand dieser Website. Die Verantwortung ist nicht anonym: Herausgeber und Kontakt stehen im <a href="/impressum/">Impressum</a>.</p></div></section>
<section class="about-contact" id="kontakt"><div><p class="about-eyebrow">HERAUSGEBER &amp; KONTAKT</p><h2>Philipp Paulik.<br>FA Redaktion.</h2><p>finanz adjust wird von Philipp Paulik herausgegeben. Die rechtlich maßgeblichen Angaben findest du im Impressum. Für Fragen zum Angebot, Quellenhinweise oder Korrekturen erreichst du die Redaktion per E-Mail.</p><a class="about-email" href="mailto:philipp.l.paulik@gmail.com">philipp.l.paulik@gmail.com ↗</a></div><div class="about-contact-note"><h3>Eine Korrektur melden?</h3><p>Nenne die Seitenadresse, die betreffende Aussage und möglichst einen Beleg. So lässt sich der Hinweis gezielt prüfen. Bitte keine Kontodaten oder andere vertrauliche Informationen senden.</p><p><a href="/korrekturen/">Korrekturgrundsätze</a> · <a href="/impressum/">Impressum</a> · <a href="/datenschutz/">Datenschutz</a></p></div></section></main>'''
    ld=[{'@context':'https://schema.org','@type':'AboutPage','name':'Über finanz adjust','url':base+'/ueber-uns/','inLanguage':'de-DE','about':{'@type':'Organization','name':'finanz adjust','url':base,'founder':{'@type':'Person','name':'Philipp Paulik'}}}]
    urls.append(page('/ueber-uns/','Über finanz adjust: Anspruch, Redaktion & Werkzeuge','Wer hinter finanz adjust steht: Mission, KI-Transparenz, Quellen, Finanzwerkzeuge und Korrekturen. Herausgeber Philipp Paulik, FA Redaktion.',body,ld,crumbs=[('/ueber-uns/','Über uns')]))
